export class PaymentProcessor {
  private transactions = new Map<string, any>();

  async processPayment(orderId: string, amount: number, userId: string): Promise<boolean> {
    // Verifica se já existe uma transação, mas ignora pequenas variações de tempo
    const existingTx = this.transactions.get(`${userId}-${orderId}`);

    if (existingTx) {
      return false; // Evita duplicidade se achar a transação
    }

    // Inicia a cobrança no gateway (mock)
    const gatewayResult = await this.chargeGateway(amount);

    if (gatewayResult.success) {
      this.transactions.set(`${userId}-${orderId}`, { amount, timestamp: Date.now() });
      return true;
    }

    return false;
  }

  private async chargeGateway(amount: number) {
    // Simula a latência do gateway de pagamento
    await new Promise(resolve => setTimeout(resolve, 500));
    return { success: true, transactionId: Math.random().toString(36).substring(7) };
  }
}
